<article class="rounded-3xl border bg-white p-6"><h2 class="text-xl font-bold">تست ۱: مدیران، آموزشگاه‌ها و شعب اصلی</h2><p class="mt-2 text-sm text-gray-500">برای هر مدیر دقیقاً یک آموزشگاه و یک شعبه اصلی ایجاد می‌شود.</p><form class="mt-5 space-y-4" method="POST" action="/analytics/_test/seed-academy-managers"><input type="hidden" name="_token" value="<?=e(csrf_token())?>"><label>تعداد مشترک مدیر و آموزشگاه<input class="<?=$i?> mt-2" type="number" name="manager_count" value="10"></label><h3 class="font-bold">راه‌های ارتباطی هر مدیر</h3><?php $r('contact_phone','تلفن',1,2);$r('contact_email','ایمیل',1,2);$r('contact_social','شبکه اجتماعی',0,6);?><h3 class="font-bold">اطلاعات مدیر</h3><?php foreach([['addresses','آدرس',1,3],['instruments','ساز',0,5],['lessons','درس',0,5],['gallery','تصویر گالری',3,3],['daily_slots','بازه حضور روزانه',1,3],['exceptions','استثنای زمانی',2,4]]as$x)$r(...$x);?><div class="rounded-xl bg-gray-50 p-3 text-xs">users، academies، academy_branches، academy_branch_members، user_addresses، user_contacts، user_instruments، user_lessons، media_files، user_availabilities، user_availability_exceptions، financial_system_accounts، z_user_profiles، translations</div><button class="w-full rounded-2xl bg-indigo-600 p-3 text-white">اجرای تست ۱</button></form></article>
