<script>window.runUnifiedFixtureTest=async function(){const forms=[...document.querySelectorAll('#tests form')].filter(f=>!f.action.includes('delete'));const target=document.createElement('form');target.method='POST';target.action='/analytics/_test/run-all';forms.forEach(form=>new FormData(form).forEach((value,key)=>{if(key==='_token'&&target.querySelector('[name="_token"]'))return;const input=document.createElement('input');input.type='hidden';input.name=key;input.value=value;target.appendChild(input);}));document.body.appendChild(target);if(await AppDialog.confirm('تمام مراحل اجرا شوند؟'))target.submit();else target.remove();};</script>
